  "prediction_basis_card_ids": ["C01","C05","C14","C08","C11","C13","C02","C06","C07","C12"],
  "claims": [
    {
      "claim": "Transferable L1 gold-context records in fasted/non-cirrhotic oral settings report absolute F values well above 20%: melperone 54–67%, vernakalant 58–71%, suvorexant 82%, propylthiouracil 77%, BI 425809 71.6%, levofloxacin ~100%, and hyperforin reported as high.",
      "card_ids": ["C01","C05","C14","C08","C11","C13","C02","C06","C07","C12"]
    },
    {
      "claim": "The query is a lipophilic weak base with low TPSA, low HBD, low rotatable-bond count, and a cyclic thiourea; this profile is consistent with the high-F lipophilic weak-base and thiourea-containing contexts, and no transferable L1 record provides affirmative evidence of F < 20%.",
      "card_ids": ["C02","C08","C13","C01"]
    },
    {
      "claim": "L3 oral Cmax records for DA-8010 (M01) show measurable, roughly dose-proportional oral exposure in fasted humans (e.g., 1210 pg/ml at 10 mg and 2230 pg/ml at 20 mg), but they lack AUC and an IV comparator, so they support absorption only and do not quantify absolute F.",
      "card_ids": ["C21","C25"]
    },
    {
      "claim": "L3 sparfloxacin/sucralfate and PNU-288034 records involve different chemotypes and interaction/formulation contexts and provide no absolute F value; they are not applicable to the query.",
      "card_ids": ["C22","C26","C30"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C21","C22","C23","C24","C25","C26","C27","C28","C29","C30","C31","C32"]
    }
  ],
  "evidence_gaps": [
    "No direct query-specific absolute oral bioavailability or matched oral-versus-IV exposure measurement is available.",
    "L3 records provide Cmax only, without AUC or IV comparator, so they cannot establish F >= 20% for the query.",
    "No experimental solubility, permeability, first-pass, or metabolic-stability data are available for the query; the physicochemical prior is uncertain.",
    "Training contexts are not exact structural analogs of the query, so transfer is qualitative rather than definitive.",
    "No affirmative low-F evidence from a transferable context is present; the only low L2 value (phytoene in micelle, 4.3%) is not applicable to the query."
  ],
  "decision_summary": "Predicted high (F >= 20%) with low confidence. L1 gold-context records transferable to a fasted, non-cirrhotic small-molecule oral setting all report F well above 20%, and the query's lipophilic weak-base/thiourea profile is consistent with absorption. L3 adds only oral Cmax data (mainly DA-8010) that weakly support oral exposure but do not quantify F, and no transferable affirmative low-F evidence is present; therefore the prior high prediction is kept."
}

